function loadColumnOrder(): ColumnId[] {
  try {
    const raw = localStorage.getItem(COLUMN_ORDER_STORAGE_KEY);
    if (!raw) return DEFAULT_COLUMN_ORDER;
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return DEFAULT_COLUMN_ORDER;
    const known = parsed.filter((id): id is ColumnId => DEFAULT_COLUMN_ORDER.includes(id as ColumnId));
    // Append columns that may have been added since the order was saved.
    const missing = DEFAULT_COLUMN_ORDER.filter((id) => !known.includes(id));
    return [...known, ...missing];
  } catch {
    return DEFAULT_COLUMN_ORDER;
  }
}

function moveColumn(order: ColumnId[], source: ColumnId, target: ColumnId, side: 'before' | 'after'): ColumnId[] {
  if (source === target) return order;
  const next = order.filter((id) => id !== source);
  const targetIndex = next.indexOf(target);
  next.splice(side === 'before' ? targetIndex : targetIndex + 1, 0, source);
  return next;
}

interface DragState {
  source: ColumnId | null;
  target: ColumnId | null;
  side: 'before' | 'after';
}

