const SelectableTable = withTableSelection<Order>(Table);

type ColumnId = 'number' | 'customer' | 'status' | 'items' | 'total' | 'payment' | 'city' | 'createdAt';
type SortOrder = 'asc' | 'desc';
interface SortState {
  column: ColumnId;
  order: SortOrder;
}
interface ColumnDef {
