  title: string;
  width?: number;
  align?: 'start' | 'end';
  primary?: boolean;
  sortable?: boolean;
  defaultSortOrder?: SortOrder;
  template?: (order: Order) => React.ReactNode;
  compare?: (a: Order, b: Order) => number;
